// Moonbrim — starfield + site-wide "chrome" bootstrap. No dependencies, no tracking.
//
// This file is intentionally more than a starfield: it is the ONE script every
// page on the site loads — including /stories/ and /stories/<slug>/, which are
// regenerated by pipeline/site_gen.py (a different, read-only-to-this-pass
// codebase) and whose <head>/<script> tags cannot be hand-edited here without
// a future generator run reverting the edit. So anything that must appear on
// EVERY page — the time-of-day sky, the lantern (lights-off) + ambience
// toggles, the footer moon phase, the "For Grown-ups" footer link, the
// cloud-drift page transition — is bootstrapped from here, once, via plain
// DOM injection. Page-specific script (the hero, the ritual, the Story Sky)
// lives in its own file and is linked only from the pages that need it.
(function () {
  "use strict";

  var reduceMotion =
    window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  var LS_LIGHTS_OFF = "moonbrim:lights-off";
  var LS_AMBIENCE = "moonbrim:ambience";

  // ---------------------------------------------------------------------
  // 1. Starfield (existing convention) — twinkle + a subset that drifts.
  // ---------------------------------------------------------------------
  (function starfield() {
    var host = document.querySelector(".stars");
    if (!host) return;

    var count = Math.min(120, Math.round((window.innerWidth * window.innerHeight) / 9000));
    var frag = document.createDocumentFragment();

    for (var i = 0; i < count; i++) {
      var star = document.createElement("span");
      var size = (Math.random() * 1.8 + 0.6).toFixed(2);
      star.className = "star";
      star.style.left = (Math.random() * 100).toFixed(2) + "%";
      star.style.top = (Math.random() * 100).toFixed(2) + "%";
      star.style.width = size + "px";
      star.style.height = size + "px";
      star.style.boxShadow = "0 0 " + (size * 2).toFixed(1) + "px rgba(255,255,255,0.85)";
      star.style.animationDuration = (Math.random() * 3 + 2.5).toFixed(2) + "s";
      star.style.animationDelay = (Math.random() * 4).toFixed(2) + "s";

      // ~1 in 5 stars also drifts slowly — skipped entirely under
      // reduced-motion rather than just slowed down.
      if (!reduceMotion && Math.random() < 0.2) {
        star.className += " drift";
        star.style.setProperty("--drift-x", (Math.random() * 26 - 13).toFixed(1) + "px");
        star.style.setProperty("--drift-y", (Math.random() * 22 - 11).toFixed(1) + "px");
        star.style.setProperty("--drift-dur", (Math.random() * 30 + 30).toFixed(1) + "s");
      }
      frag.appendChild(star);
    }

    // Fireflies — only after 20:00 local, through to dawn. A tasteful few,
    // never distracting. Static (no drift) under reduced-motion rather than
    // removed outright, since a few motionless warm points still read as
    // atmosphere without being disruptive.
    var hour = new Date().getHours();
    var fireflyTime = hour >= 20 || hour < 5;
    if (fireflyTime) {
      var fireflyCount = Math.min(9, Math.max(4, Math.round(window.innerWidth / 260)));
      for (var f = 0; f < fireflyCount; f++) {
        var fly = document.createElement("span");
        fly.className = "firefly";
        fly.style.left = (8 + Math.random() * 84).toFixed(2) + "%";
        fly.style.top = (35 + Math.random() * 55).toFixed(2) + "%";
        if (!reduceMotion) {
          fly.style.animationDuration =
            (Math.random() * 10 + 14).toFixed(1) + "s, " + (Math.random() * 3 + 2).toFixed(1) + "s";
          fly.style.animationDelay = (Math.random() * 6).toFixed(1) + "s";
          fly.style.setProperty("--fx1", (Math.random() * 24 - 12).toFixed(1) + "px");
          fly.style.setProperty("--fy1", (Math.random() * -24 - 6).toFixed(1) + "px");
          fly.style.setProperty("--fx2", (Math.random() * -20 - 6).toFixed(1) + "px");
          fly.style.setProperty("--fy2", (Math.random() * 16 - 8).toFixed(1) + "px");
          fly.style.setProperty("--fx3", (Math.random() * 18).toFixed(1) + "px");
          fly.style.setProperty("--fy3", (Math.random() * 18).toFixed(1) + "px");
        }
        frag.appendChild(fly);
      }
    }

    host.appendChild(frag);
  })();

  // ---------------------------------------------------------------------
  // 2. Time-of-day sky bucket — a class on <html>, CSS does the rest.
  // ---------------------------------------------------------------------
  (function timeOfDay() {
    var hour = new Date().getHours();
    var bucket = null; // null = "day" (8-17), the existing default look
    if (hour >= 17 && hour < 19) bucket = "tod-dusk";
    else if (hour >= 19 && hour < 21) bucket = "tod-evening";
    else if (hour >= 21 || hour < 5) bucket = "tod-deep-night";
    else if (hour >= 5 && hour < 8) bucket = "tod-dawn";
    if (bucket) document.documentElement.classList.add(bucket);
  })();

  // ---------------------------------------------------------------------
  // 3. Moon phase — pure-JS synodic calc, real drawn moon (not an emoji).
  //    Exposed on window.Moonbrim.moon so the ritual's goodnight screen can
  //    reuse the exact same drawing code instead of a second copy of it.
  // ---------------------------------------------------------------------
  var SYNODIC_DAYS = 29.53058867;
  var NEW_MOON_REF_UTC = Date.UTC(2000, 0, 6, 18, 14, 0);
  var PHASE_NAMES = [
    "New moon",
    "Waxing crescent",
    "First quarter",
    "Waxing gibbous",
    "Full moon",
    "Waning gibbous",
    "Last quarter",
    "Waning crescent",
  ];

  function moonPhase(date) {
    var days = (date.getTime() - NEW_MOON_REF_UTC) / 86400000;
    var phase = (days % SYNODIC_DAYS) / SYNODIC_DAYS;
    if (phase < 0) phase += 1;
    return phase; // 0..1, 0 = new, 0.5 = full
  }

  function moonPhaseName(phase) {
    var idx = Math.floor(((phase + 0.0625) % 1) / 0.125) % 8;
    if (idx < 0) idx += 8;
    return PHASE_NAMES[idx];
  }

  // Renders a small SVG moon whose lit shape is built from two arcs (the
  // outer limb + the terminator ellipse), the standard construction for an
  // accurate phase silhouette — not a flat emoji glyph. Styled to match the
  // logo's lantern glow (gold fill + soft drop-shadow).
  function renderMoonSVG(container, size, phase) {
    if (!container) return;
    size = size || 20;
    var r = size / 2 - 1;
    var cx = size / 2;
    var cy = size / 2;
    var theta = phase * 2 * Math.PI;
    var rxSigned = r * Math.cos(theta);
    var rxAbs = Math.abs(rxSigned).toFixed(2);
    var sweep2 = rxSigned >= 0 ? 1 : 0;
    var litPath =
      "M " + cx + " " + (cy - r) +
      " A " + r + " " + r + " 0 0 1 " + cx + " " + (cy + r) +
      " A " + rxAbs + " " + r + " 0 0 " + sweep2 + " " + cx + " " + (cy - r) +
      " Z";
    var svg =
      '<svg viewBox="0 0 ' + size + " " + size + '" width="' + size + '" height="' + size + '" role="img" aria-hidden="true">' +
      '<circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="#131c3d" stroke="rgba(242,200,121,0.35)" stroke-width="0.6"/>' +
      '<path d="' + litPath + '" fill="#ffe3b3"/>' +
      "</svg>";
    container.innerHTML = svg;
  }

  window.Moonbrim = window.Moonbrim || {};
  window.Moonbrim.moon = {
    phase: moonPhase,
    name: moonPhaseName,
    render: function (container, size) {
      renderMoonSVG(container, size, moonPhase(new Date()));
    },
  };

  // Inject the moon-phase widget into every <footer> on the site.
  (function footerMoon() {
    var footer = document.querySelector("footer");
    if (!footer) return;
    var phase = moonPhase(new Date());
    var name = moonPhaseName(phase);
    var row = document.createElement("div");
    row.className = "moon-phase-row";
    var glyph = document.createElement("span");
    glyph.className = "moon-phase";
    glyph.setAttribute("title", name);
    renderMoonSVG(glyph, 20, phase);
    var label = document.createElement("span");
    label.textContent = name + " tonight";
    row.appendChild(glyph);
    row.appendChild(label);
    footer.insertBefore(row, footer.firstChild);
  })();

  // ---------------------------------------------------------------------
  // 4. "For Grown-ups" footer link — idempotent, every page, every footer.
  // ---------------------------------------------------------------------
  (function grownupsLink() {
    if (location.pathname.indexOf("/for-grown-ups") === 0) return;
    var footer = document.querySelector("footer");
    if (!footer) return;
    if (footer.querySelector('a[href="/for-grown-ups/"]')) return;
    var sep = document.createTextNode(" · ");
    var a = document.createElement("a");
    a.href = "/for-grown-ups/";
    a.className = "grownups-link";
    a.textContent = "For Grown-ups";
    footer.appendChild(sep);
    footer.appendChild(a);
  })();

  // ---------------------------------------------------------------------
  // 5. Ensure /assets/player.js is present site-wide. It ships the shared
  //    yt-facade delegation + watched-marking + lights-off pause/handoff
  //    contract; some generator-owned pages (e.g. /stories/) only link
  //    stars.js + constellation.js, so this file guarantees player.js loads
  //    everywhere without hand-editing generated HTML.
  // ---------------------------------------------------------------------
  function ensureScript(src, onload) {
    var existing = document.querySelector('script[src="' + src + '"]');
    if (existing) {
      if (onload) existing.addEventListener("load", onload, { once: true });
      return;
    }
    var s = document.createElement("script");
    s.src = src;
    if (onload) s.addEventListener("load", onload, { once: true });
    document.body.appendChild(s);
  }
  ensureScript("/assets/player.js");

  // ---------------------------------------------------------------------
  // 6. Lantern (lights-off) + ambience toggles — fixed corner, every page.
  // ---------------------------------------------------------------------
  (function toggles() {
    var lightsOffOn = localStorage.getItem(LS_LIGHTS_OFF) === "1";
    var ambienceOn = localStorage.getItem(LS_AMBIENCE) === "1";

    if (lightsOffOn) document.documentElement.classList.add("lights-off");

    var overlay = document.createElement("div");
    overlay.className = "lights-off-overlay";
    overlay.setAttribute("aria-hidden", "true");
    document.body.appendChild(overlay);

    var moonWrap = document.createElement("div");
    moonWrap.className = "lights-off-moon-wrap";
    moonWrap.innerHTML =
      '<span class="moon-phase" aria-hidden="true"></span>' +
      '<div class="lights-off-progress" aria-hidden="true"><div class="lights-off-progress-bar"></div></div>' +
      "<p>Lights off. Playing softly.</p>";
    document.body.appendChild(moonWrap);
    renderMoonSVG(moonWrap.querySelector(".moon-phase"), 68, moonPhase(new Date()));

    var lantern = document.createElement("button");
    lantern.type = "button";
    lantern.className = "lantern-toggle";
    lantern.setAttribute("aria-pressed", lightsOffOn ? "true" : "false");
    lantern.setAttribute("aria-label", "Toggle lights-off mode");
    lantern.title = "Lights off";
    lantern.innerHTML =
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<path d="M9 3h6l1.2 4H7.8L9 3Z"/><path d="M7.8 7h8.4l1 10a2 2 0 0 1-2 2.2H8.8a2 2 0 0 1-2-2.2l1-10Z"/>' +
      '<path d="M10 19.2V21M14 19.2V21"/></svg>';
    document.body.appendChild(lantern);

    var ambience = document.createElement("button");
    ambience.type = "button";
    ambience.className = "ambience-toggle";
    ambience.setAttribute("aria-pressed", ambienceOn ? "true" : "false");
    ambience.setAttribute("aria-label", "Toggle night ambience sound");
    ambience.title = "Night ambience";
    ambience.innerHTML =
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<path d="M4 15c1-3 1-6-1-8 3 0 5 2 6 4M9 8c2 1 3 4 2 7"/>' +
      '<circle cx="17" cy="9" r="1.1" fill="currentColor" stroke="none"/>' +
      '<circle cx="19.5" cy="14" r="0.8" fill="currentColor" stroke="none"/>' +
      "</svg>";
    document.body.appendChild(ambience);

    var ambienceAudio = null;
    function getAmbienceAudio() {
      if (!ambienceAudio) {
        ambienceAudio = new Audio("/assets/ambience.m4a");
        ambienceAudio.loop = true;
        ambienceAudio.preload = "none";
        ambienceAudio.volume = 0.16;
      }
      return ambienceAudio;
    }

    lantern.addEventListener("click", function () {
      var next = !document.documentElement.classList.contains("lights-off");
      localStorage.setItem(LS_LIGHTS_OFF, next ? "1" : "0");
      lantern.setAttribute("aria-pressed", next ? "true" : "false");
      document.documentElement.classList.toggle("lights-off", next);
      if (window.Moonbrim && window.Moonbrim.player && window.Moonbrim.player.applyLightsOff) {
        window.Moonbrim.player.applyLightsOff(next);
      }
    });

    ambience.addEventListener("click", function () {
      var next = ambience.getAttribute("aria-pressed") !== "true";
      ambience.setAttribute("aria-pressed", next ? "true" : "false");
      localStorage.setItem(LS_AMBIENCE, next ? "1" : "0");
      var audio = getAmbienceAudio();
      if (next) audio.play().catch(function () {});
      else audio.pause();
    });
  })();

  // ---------------------------------------------------------------------
  // 7. Cursor / touch glow near the hero (index.html only — no-op elsewhere
  //    since the query simply finds nothing).
  // ---------------------------------------------------------------------
  (function heroGlow() {
    if (reduceMotion) return;
    var hero = document.querySelector(".hero");
    if (!hero) return;
    function move(x, y) {
      var rect = hero.getBoundingClientRect();
      var px = ((x - rect.left) / rect.width) * 100;
      var py = ((y - rect.top) / rect.height) * 100;
      hero.style.setProperty("--glow-x", px.toFixed(1) + "%");
      hero.style.setProperty("--glow-y", py.toFixed(1) + "%");
    }
    hero.addEventListener("pointermove", function (e) {
      move(e.clientX, e.clientY);
    });
    hero.addEventListener(
      "touchmove",
      function (e) {
        if (e.touches && e.touches[0]) move(e.touches[0].clientX, e.touches[0].clientY);
      },
      { passive: true }
    );
  })();

  // ---------------------------------------------------------------------
  // 8. Cloud-drift page transitions — soft fade between navigations.
  // ---------------------------------------------------------------------
  (function cloudDrift() {
    if (reduceMotion) return;
    document.addEventListener("click", function (e) {
      var a = e.target && e.target.closest ? e.target.closest("a") : null;
      if (!a) return;
      if (a.target === "_blank" || a.hasAttribute("download")) return;
      var href = a.getAttribute("href");
      if (!href || href.charAt(0) === "#" || href.indexOf("mailto:") === 0 || href.indexOf("tel:") === 0) return;
      if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
      var url;
      try {
        url = new URL(href, location.href);
      } catch (err) {
        return;
      }
      if (url.origin !== location.origin) return;
      e.preventDefault();
      document.body.classList.add("page-leaving");
      setTimeout(function () {
        location.href = url.href;
      }, 180);
    });
  })();
})();
